-- Курс 98: Руководитель новой формации — мини-MBA с ИИ. По мотивам открытой модели компетенций корпоративных университетов. Цена 5 990 ₽.
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating)
SELECT 98,'Руководитель новой формации: мини-MBA для лидеров бизнеса с ИИ','business','adult',48,8,26,'Практическая программа для руководителей и собственников малого бизнеса. Пять управленческих компетенций — управление собой, системное мышление, управление результатом, развитие команды и клиентоцентричность — плюс управление изменениями по ADKAR, проекты и гибкие методы и модуль об ИИ в работе руководителя. Каждый модуль заканчивается практикой на задачах вашего бизнеса, в финале — программа развития команды.','["Управляете своим временем, энергией и решениями в неопределённости", "Находите корневые причины проблем и решаете их на данных", "Ставите цели по OKR и KPI и выстраиваете ритм управления", "Нанимаете, адаптируете, делегируете и даёте обратную связь", "Проводите команду через изменения по модели ADKAR", "Ведёте проекты с помощью гибких методов", "Используете ИИ в управленческих задачах и считаете эффект", "Развиваете клиентоцентричность и растите лидеров через менторинг"]'::jsonb,'Собственники малого и среднего бизнеса, новые руководители и тимлиды, руководители отделов, специалисты, готовящиеся к управленческой роли.','["опыт управления не обязателен", "работающий бизнес, команда или учебный кейс для практики"]'::jsonb,'Короткие уроки по делу и практика на собственных задачах. Каждый модуль заканчивается рабочим инструментом: картой развития, дашбордом, планом изменений. ИИ-наставник 24/7 разбирает кейсы, проверяет задания и помогает готовиться к сложным разговорам.','Итоговый проект: программа развития команды — план изменения по ADKAR, ИИ-инициатива с расчётом эффекта и дашборд руководителя.',true,'editorial_manual',1,false,'18+'
WHERE NOT EXISTS (SELECT 1 FROM t_p78828167_tutor_platform_1.course_curricula WHERE course_id=98);

INSERT INTO t_p78828167_tutor_platform_1.course_lessons (course_id,module_index,module_title,module_description,lesson_index,lesson_title,lesson_summary,lesson_type,estimated_minutes,topics,skills_acquired,homework_description,is_preview,sort_order)
SELECT 98,
  m.mi::int,
  m.mod->>'t',
  m.mod->>'d',
  l.li::int,
  l.les->>0,
  l.les->>1,
  l.les->>2,
  CASE l.les->>2 WHEN 'theory' THEN 25 WHEN 'project' THEN 45 ELSE 35 END,
  l.les->3,
  '[]'::jsonb,
  'Примените инструмент урока «' || (l.les->>0) || '» к своей команде или бизнесу и сохраните результат в рабочую тетрадь курса.',
  (m.mi = 1 AND l.li = 1),
  ((m.mi - 1) * 6 + l.li)::int
FROM jsonb_array_elements('[{"t": "Модуль 1. Управление собой: опора руководителя", "d": "Эмоциональный интеллект, энергия и решения под давлением.", "l": [["Руководитель новой формации: кто это", "Почему навыков специалиста мало и что меняется, когда вы отвечаете за людей.", "theory", ["Роль руководителя", "Модель компетенций", "Самодиагностика", "Цели курса"]], ["Эмоциональный интеллект на практике", "Четыре навыка EQ: распознать, понять, управлять, влиять.", "theory", ["Эмоциональный интеллект", "Самосознание", "Эмпатия", "Саморегуляция"]], ["Стресс и энергия: личная система", "Как не выгореть: ритм, восстановление, границы.", "theory", ["Стресс", "Энергия", "Выгорание", "Ритуалы"]], ["Решения в неопределённости", "Когда данных мало: быстрые и медленные решения, цена ошибки.", "theory", ["Решения", "Неопределённость", "Когнитивные искажения", "Риск"]], ["Время руководителя", "Матрица приоритетов, блоки фокуса и честный аудит недели.", "practice", ["Приоритеты", "Фокус", "Календарь", "Аудит времени"]], ["Практика: карта развития руководителя", "Самооценка по 5 компетенциям и план на 90 дней.", "practice", ["Самооценка", "Компетенции", "План развития", "90 дней"]]]}, {"t": "Модуль 2. Системное мышление и решение проблем", "d": "Видеть причины, а не симптомы.", "l": [["Система, а не набор событий", "Петли обратной связи и почему «тушить пожары» не работает.", "theory", ["Системное мышление", "Петли", "Причины", "Симптомы"]], ["Пошаговое решение проблем", "Определить, разложить, приоритизировать, проверить гипотезы.", "theory", ["Проблема", "Декомпозиция", "Гипотезы", "Проверка"]], ["Дерево причин и «5 почему»", "Инструменты поиска корневой причины на примерах малого бизнеса.", "practice", ["Дерево причин", "5 почему", "Исикава", "Корневая причина"]], ["Решения на данных", "Какие цифры смотреть и как не обмануть себя графиком.", "theory", ["Данные", "Метрики", "Выборка", "A/B-тест"]], ["Креативные техники для управленца", "Мозговой штурм, SCAMPER и обратная постановка задачи.", "practice", ["Креативность", "Мозговой штурм", "SCAMPER", "Идеи"]], ["Практика: разбор реальной проблемы", "Проблема вашего бизнеса от симптома до плана решения.", "practice", ["Кейс", "Анализ", "Решение", "План"]]]}, {"t": "Модуль 3. Управление результатом", "d": "Цели, метрики и культура ответственности.", "l": [["От стратегии к задачам", "Как цель компании превращается в задачу сотрудника.", "theory", ["Стратегия", "Каскадирование", "Цели", "Задачи"]], ["OKR и KPI без бюрократии", "Когда нужны OKR, когда KPI и как не утонуть в таблицах.", "theory", ["OKR", "KPI", "Метрики", "Баланс"]], ["Постановка задач, которые выполняют", "Ожидаемый результат, критерии, сроки и ресурсы.", "practice", ["Постановка задач", "Критерии", "Сроки", "Контроль"]], ["Культура ответственности", "Владение результатом вместо поиска виноватых.", "theory", ["Ответственность", "Ownership", "Ошибки", "Доверие"]], ["Ритм управления", "Планёрки, еженедельные встречи и ретроспективы, которые экономят время.", "practice", ["Встречи", "Планёрка", "Ретроспектива", "Ритм"]], ["Практика: дашборд руководителя", "5–7 ключевых показателей вашего подразделения на одной странице.", "practice", ["Дашборд", "Показатели", "Таблица", "Ритм"]]]}, {"t": "Модуль 4. Команда: найм, развитие, вовлечённость", "d": "Собрать команду и вырастить сильных людей.", "l": [["Профиль роли и найм", "Кого ищем, как проводить интервью по компетенциям.", "theory", ["Найм", "Профиль роли", "Интервью", "Компетенции"]], ["Адаптация нового сотрудника", "План первых 30–60–90 дней и наставник.", "practice", ["Адаптация", "Онбординг", "Наставник", "90 дней"]], ["Делегирование по уровням", "Что, кому и с какой степенью свободы отдавать.", "theory", ["Делегирование", "Уровни", "Зрелость", "Контроль"]], ["Обратная связь, которая работает", "Модели SBI и «развивающая обратная связь» без обид.", "practice", ["Обратная связь", "SBI", "Похвала", "Сложный разговор"]], ["Мотивация и вовлечённость", "Деньги, смысл, рост и признание: что работает в 2026 году.", "theory", ["Мотивация", "Вовлечённость", "Признание", "Удержание"]], ["Практика: one-to-one встреча", "Сценарий личной встречи и разбор типичных ошибок.", "practice", ["One-to-one", "Сценарий", "Развитие", "Доверие"]]]}, {"t": "Модуль 5. Управление изменениями", "d": "Как провести команду через перемены по модели ADKAR.", "l": [["Почему изменения проваливаются", "Типичные причины и цена сопротивления.", "theory", ["Изменения", "Сопротивление", "Провалы", "Риски"]], ["Модель ADKAR шаг за шагом", "Осознание, желание, знание, способность, закрепление.", "theory", ["ADKAR", "Осознание", "Желание", "Закрепление"]], ["Диагностика готовности команды", "Как понять, кто готов, а кому нужна помощь.", "practice", ["Диагностика", "Готовность", "Карта стейкхолдеров", "Опрос"]], ["Коммуникация перемен", "Что, кому и когда говорить, чтобы люди поддержали изменения.", "practice", ["Коммуникация", "Послание", "Каналы", "Вопросы"]], ["Работа с сопротивлением", "Пять типов сопротивления и как отвечать на каждый.", "theory", ["Сопротивление", "Страхи", "Переговоры", "Вовлечение"]], ["Практика: план изменения", "План внедрения одного изменения в вашей компании по ADKAR.", "practice", ["План", "ADKAR", "Метрики", "Сроки"]]]}, {"t": "Модуль 6. Проекты и гибкие методы", "d": "Доводить инициативы до результата.", "l": [["Проект: цели, рамки, стейкхолдеры", "Устав проекта на одной странице.", "theory", ["Проект", "Устав", "Стейкхолдеры", "Рамки"]], ["Планирование и риски", "Вехи, ресурсы, реестр рисков и план реагирования.", "practice", ["Планирование", "Вехи", "Риски", "Ресурсы"]], ["Scrum и канбан для небольшой команды", "Спринты, доска задач и ежедневные короткие встречи.", "theory", ["Scrum", "Канбан", "Спринт", "Доска"]], ["Гибрид: когда водопад, когда agile", "Выбор подхода под задачу и бизнес.", "theory", ["Agile", "Водопад", "Гибрид", "Выбор"]], ["Мониторинг и отчётность", "Статус проекта за 5 минут: светофор и контрольные точки.", "practice", ["Мониторинг", "Статус", "Отчёт", "Контрольные точки"]], ["Практика: запуск мини-проекта", "Устав, план и доска задач для реальной инициативы.", "practice", ["Устав", "План", "Доска", "Запуск"]]]}, {"t": "Модуль 7. ИИ в работе руководителя", "d": "Человек, дополненный ИИ: эффективность без иллюзий.", "l": [["Что ИИ меняет в управлении", "Где нейросети уже экономят время руководителя.", "theory", ["Генеративный ИИ", "Тренды", "Эффективность", "Роли"]], ["Промпты для управленческих задач", "Письма, протоколы, анализ, подготовка к переговорам.", "practice", ["Промпты", "Шаблоны", "Протоколы", "Анализ"]], ["ИИ-ассистент для команды", "Регламенты, база знаний и автоматизация рутины.", "practice", ["ИИ-ассистент", "База знаний", "Регламенты", "Автоматизация"]], ["Как посчитать эффект от ИИ", "Время, деньги и качество: считаем экономику внедрения.", "theory", ["Эффект", "Экономика", "Окупаемость", "Метрики"]], ["Риски ИИ и правила работы с данными", "Ошибки моделей, конфиденциальность и 152-ФЗ.", "theory", ["Риски", "Галлюцинации", "Данные", "152-ФЗ"]], ["Практика: ИИ-инициатива", "Выбор процесса, пилот и критерии успеха.", "practice", ["Пилот", "Процесс", "Критерии", "Внедрение"]]]}, {"t": "Модуль 8. Клиентоцентричность, менторинг и итоговый проект", "d": "Лидер, который растит людей и бизнес.", "l": [["Клиентоцентричность как способ управлять", "Путь клиента, голос клиента и решения от клиента.", "theory", ["Клиентоцентричность", "CJM", "NPS", "Сервис"]], ["Переговоры и влияние", "Интересы вместо позиций и подготовка к трудному разговору.", "practice", ["Переговоры", "Влияние", "Интересы", "Аргументы"]], ["Менторинг: растим лидеров", "Роль ментора, формат встреч и договорённости.", "theory", ["Менторинг", "Наставничество", "Встречи", "Рост"]], ["Личный бренд руководителя", "Как говорить о себе, команде и компании.", "theory", ["Личный бренд", "Публичность", "Выступления", "Доверие"]], ["Подготовка итогового проекта", "Собираем материалы модулей в единую программу трансформации.", "practice", ["Проект", "Структура", "Метрики", "Презентация"]], ["Итоговый проект: программа развития команды", "План изменений, ИИ-инициатива и дашборд — защита.", "project", ["Итоговый проект", "Изменения", "ИИ", "Защита"]]]}]'::jsonb) WITH ORDINALITY AS m(mod, mi)
